  vip_preview_note: { ru: "Заполните VIP-раздел ниже. Чтобы опубликовать профиль в VIP, оформите VIP Premium.", en: "Fill in your VIP section below. To publish your profile in VIP, get VIP Premium.", es: "Completa tu sección VIP abajo. Para publicar tu perfil en VIP, obtén VIP Premium.", fr: "Remplissez votre section VIP ci-dessous. Pour publier votre profil en VIP, passez au VIP Premium.", de: "Füllen Sie Ihren VIP-Bereich unten aus. Um Ihr Profil im VIP zu veröffentlichen, holen Sie VIP Premium.", pt: "Preencha sua seção VIP abaixo. Para publicar seu perfil no VIP, assine o VIP Premium.", zh: "在下方填写您的 VIP 板块。要在 VIP 中发布资料，请开通 VIP Premium。", hi: "नीचे अपना VIP अनुभाग भरें। VIP में प्रोफ़ाइल प्रकाशित करने के लिए VIP Premium लें।", bn: "নিচে আপনার VIP বিভাগ পূরণ করুন। VIP-তে প্রোফাইল প্রকাশ করতে VIP Premium নিন।", ur: "نیچے اپنا VIP سیکشن بھریں۔ VIP میں پروفائل شائع کرنے کے لیے VIP Premium لیں۔", ar: "املأ قسم VIP أدناه. لنشر ملفك في VIP، احصل على VIP Premium." },
  vip_buy_publish: { ru: "Купить VIP и опубликовать", en: "Buy VIP & publish", es: "Comprar VIP y publicar", fr: "Acheter VIP et publier", de: "VIP kaufen & veröffentlichen", pt: "Comprar VIP e publicar", zh: "购买 VIP 并发布", hi: "VIP खरीदें और प्रकाशित करें", bn: "VIP কিনুন ও প্রকাশ করুন", ur: "VIP خریدیں اور شائع کریں", ar: "شراء VIP والنشر" },
  vip_live: { ru: "Ваш VIP-профиль опубликован", en: "Your VIP profile is live", es: "Tu perfil VIP está publicado", fr: "Votre profil VIP est en ligne", de: "Ihr VIP-Profil ist live", pt: "Seu perfil VIP está no ar", zh: "您的 VIP 资料已上线", hi: "आपकी VIP प्रोफ़ाइल लाइव है", bn: "আপনার VIP প্রোফাইল লাইভ", ur: "آپ کا VIP پروفائل لائیو ہے", ar: "ملفك في VIP منشور الآن" },
